// CI_Plus_Host_apb: APB4 register wrapper around CI_Plus_Host_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/CI_Plus_Host.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/CI_Plus_Host.md
// ============================================================================
module CI_Plus_Host_apb #(
  parameter logic [3:0] AXI_ID = 4'd11
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic ci_vcc_en,
  output logic ci_reset,
  input logic ci_cd_n,
  output logic [14:0] ci_a,
  output logic [7:0] ci_d_o,
  output logic ci_d_oe,
  input logic [7:0] ci_d_i,
  output logic ci_ce_n,
  output logic ci_reg_n,
  output logic ci_oe_n,
  output logic ci_we_n,
  output logic ci_iord_n,
  output logic ci_iowr_n,
  input logic ci_wait_n,
  input logic ci_ireq_n,
  input logic [7:0] ts_in_data,
  input logic ts_in_valid,
  input logic ts_in_sop,
  output logic [7:0] ts_out_data,
  output logic ts_out_valid,
  output logic ts_out_sop,
  output logic [7:0] ci_mo_data,
  output logic ci_mo_val,
  output logic ci_mo_strt,
  input logic [7:0] ci_mi_data,
  input logic ci_mi_val,
  input logic ci_mi_strt,
  output logic [3:0] m_awid,
  output logic [31:0] m_awaddr,
  output logic [7:0] m_awlen,
  output logic [2:0] m_awsize,
  output logic [1:0] m_awburst,
  output logic [2:0] m_awprot,
  output logic m_awvalid,
  input logic m_awready,
  output logic [31:0] m_wdata,
  output logic [3:0] m_wstrb,
  output logic m_wlast,
  output logic m_wvalid,
  input logic m_wready,
  input logic [3:0] m_bid,
  input logic [1:0] m_bresp,
  input logic m_bvalid,
  output logic m_bready,
  output logic [3:0] m_arid,
  output logic [31:0] m_araddr,
  output logic [7:0] m_arlen,
  output logic [2:0] m_arsize,
  output logic [1:0] m_arburst,
  output logic [2:0] m_arprot,
  output logic m_arvalid,
  input logic m_arready,
  input logic [3:0] m_rid,
  input logic [31:0] m_rdata,
  input logic [1:0] m_rresp,
  input logic m_rlast,
  input logic m_rvalid,
  output logic m_rready
);
  localparam logic [31:0] ID_VALUE = 32'h7C0B0100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [21:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd22) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_enable;
  logic          c_ts_route;
  logic          c_poll;
  logic [3:0]    c_setup;
  logic [7:0]    c_strobe;
  logic [3:0]    c_hold;
  logic [15:0]   c_wait_max;
  logic [15:0]   c_rst_clks;
  logic [15:0]   c_poll_div;
  logic [15:0]   c_fr_max;
  logic [31:0]   c_cis_addr;
  logic [15:0]   c_cis_len;
  logic [14:0]   c_cor_addr;
  logic [7:0]    c_cor_val;
  logic [31:0]   c_tx_addr;
  logic [15:0]   c_tx_len;
  logic [31:0]   c_rx_addr;
  logic [15:0]   c_rx_max;
  logic          c_power_on;
  logic          c_power_off;
  logic          c_cis_read;
  logic          c_cor_write;
  logic          c_if_reset;
  logic          c_tx_start;
  logic          c_rx_arm;
  logic          c_powered;
  logic          c_ready;
  logic          c_io_mode;
  logic          c_busy;
  logic          c_rx_full;
  logic          c_rx_ovf;
  logic          c_tx_fail;
  logic          c_err;
  logic          c_present;
  logic [7:0]    c_last_st;
  logic [15:0]   c_rx_len;
  logic [15:0]   c_tx_cnt;
  logic [15:0]   c_rx_cnt;
  logic [15:0]   c_ts_cnt;
  logic [15:0]   c_to_cnt;
  logic          c_det;
  logic          c_rdy;
  logic          c_cfg;
  logic          c_tx_done;
  logic          c_rx;
  logic          c_ireq;
  logic          c_bus_to;
  logic          c_err_irq;
  CI_Plus_Host_top #(.AXI_ID(AXI_ID)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .ci_vcc_en(ci_vcc_en),
    .ci_reset(ci_reset),
    .ci_cd_n(ci_cd_n),
    .ci_a(ci_a),
    .ci_d_o(ci_d_o),
    .ci_d_oe(ci_d_oe),
    .ci_d_i(ci_d_i),
    .ci_ce_n(ci_ce_n),
    .ci_reg_n(ci_reg_n),
    .ci_oe_n(ci_oe_n),
    .ci_we_n(ci_we_n),
    .ci_iord_n(ci_iord_n),
    .ci_iowr_n(ci_iowr_n),
    .ci_wait_n(ci_wait_n),
    .ci_ireq_n(ci_ireq_n),
    .ts_in_data(ts_in_data),
    .ts_in_valid(ts_in_valid),
    .ts_in_sop(ts_in_sop),
    .ts_out_data(ts_out_data),
    .ts_out_valid(ts_out_valid),
    .ts_out_sop(ts_out_sop),
    .ci_mo_data(ci_mo_data),
    .ci_mo_val(ci_mo_val),
    .ci_mo_strt(ci_mo_strt),
    .ci_mi_data(ci_mi_data),
    .ci_mi_val(ci_mi_val),
    .ci_mi_strt(ci_mi_strt),
    .enable(c_enable),
    .ts_route(c_ts_route),
    .poll(c_poll),
    .setup(c_setup),
    .strobe(c_strobe),
    .hold(c_hold),
    .wait_max(c_wait_max),
    .rst_clks(c_rst_clks),
    .poll_div(c_poll_div),
    .fr_max(c_fr_max),
    .cis_addr(c_cis_addr),
    .cis_len(c_cis_len),
    .cor_addr(c_cor_addr),
    .cor_val(c_cor_val),
    .tx_addr(c_tx_addr),
    .tx_len(c_tx_len),
    .rx_addr(c_rx_addr),
    .rx_max(c_rx_max),
    .power_on(c_power_on),
    .power_off(c_power_off),
    .cis_read(c_cis_read),
    .cor_write(c_cor_write),
    .if_reset(c_if_reset),
    .tx_start(c_tx_start),
    .rx_arm(c_rx_arm),
    .powered(c_powered),
    .ready(c_ready),
    .io_mode(c_io_mode),
    .busy(c_busy),
    .rx_full(c_rx_full),
    .rx_ovf(c_rx_ovf),
    .tx_fail(c_tx_fail),
    .err(c_err),
    .present(c_present),
    .last_st(c_last_st),
    .rx_len(c_rx_len),
    .tx_cnt(c_tx_cnt),
    .rx_cnt(c_rx_cnt),
    .ts_cnt(c_ts_cnt),
    .to_cnt(c_to_cnt),
    .det(c_det),
    .rdy(c_rdy),
    .cfg(c_cfg),
    .tx_done(c_tx_done),
    .rx(c_rx),
    .ireq(c_ireq),
    .bus_to(c_bus_to),
    .err_irq(c_err_irq),
    .m_awid(m_awid),
    .m_awaddr(m_awaddr),
    .m_awlen(m_awlen),
    .m_awsize(m_awsize),
    .m_awburst(m_awburst),
    .m_awprot(m_awprot),
    .m_awvalid(m_awvalid),
    .m_awready(m_awready),
    .m_wdata(m_wdata),
    .m_wstrb(m_wstrb),
    .m_wlast(m_wlast),
    .m_wvalid(m_wvalid),
    .m_wready(m_wready),
    .m_bid(m_bid),
    .m_bresp(m_bresp),
    .m_bvalid(m_bvalid),
    .m_bready(m_bready),
    .m_arid(m_arid),
    .m_araddr(m_araddr),
    .m_arlen(m_arlen),
    .m_arsize(m_arsize),
    .m_arburst(m_arburst),
    .m_arprot(m_arprot),
    .m_arvalid(m_arvalid),
    .m_arready(m_arready),
    .m_rid(m_rid),
    .m_rdata(m_rdata),
    .m_rresp(m_rresp),
    .m_rlast(m_rlast),
    .m_rvalid(m_rvalid),
    .m_rready(m_rready)
  );

  // ---------------- registers ----------------
  logic [7:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [2:0] r_CTRL;   // 12'h014 CTRL
  logic [15:0] r_TIMING;   // 12'h018 TIMING
  logic [31:0] r_WAITS;   // 12'h01C WAITS
  logic [31:0] r_POLL;   // 12'h020 POLL
  logic [31:0] r_CIS_ADDR;   // 12'h024 CIS_ADDR
  logic [15:0] r_CIS_LEN;   // 12'h028 CIS_LEN
  logic [22:0] r_COR;   // 12'h02C COR
  logic [31:0] r_TX_ADDR;   // 12'h030 TX_ADDR
  logic [15:0] r_TX_LEN;   // 12'h034 TX_LEN
  logic [31:0] r_RX_ADDR;   // 12'h038 RX_ADDR
  logic [15:0] r_RX_MAX;   // 12'h03C RX_MAX
  logic [6:0] p_CMD;   // 12'h040 CMD (pulses)

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CTRL <= 3'h0;
      r_TIMING <= 16'h0;
      r_WAITS <= 32'h0;
      r_POLL <= 32'h0;
      r_CIS_ADDR <= 32'h0;
      r_CIS_LEN <= 16'h0;
      r_COR <= 23'h0;
      r_TX_ADDR <= 32'h0;
      r_TX_LEN <= 16'h0;
      r_RX_ADDR <= 32'h0;
      r_RX_MAX <= 16'h0;
      p_CMD <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[7:0] & wmask[7:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[7:0]) | (PWDATA[7:0] & wmask[7:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CTRL <= (r_CTRL & ~wmask[2:0]) | (PWDATA[2:0] & wmask[2:0]);
      if (wr && hit[6]) r_TIMING <= (r_TIMING & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[7]) r_WAITS <= (r_WAITS & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[8]) r_POLL <= (r_POLL & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[9]) r_CIS_ADDR <= (r_CIS_ADDR & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[10]) r_CIS_LEN <= (r_CIS_LEN & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[11]) r_COR <= (r_COR & ~wmask[22:0]) | (PWDATA[22:0] & wmask[22:0]);
      if (wr && hit[12]) r_TX_ADDR <= (r_TX_ADDR & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[13]) r_TX_LEN <= (r_TX_LEN & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[14]) r_RX_ADDR <= (r_RX_ADDR & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[15]) r_RX_MAX <= (r_RX_MAX & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      p_CMD <= (wr && hit[16]) ? PWDATA[6:0] & wmask[6:0] : '0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_enable = r_CTRL[0:0];
  assign c_ts_route = r_CTRL[1:1];
  assign c_poll = r_CTRL[2:2];
  assign c_setup = r_TIMING[3:0];
  assign c_strobe = r_TIMING[11:4];
  assign c_hold = r_TIMING[15:12];
  assign c_wait_max = r_WAITS[15:0];
  assign c_rst_clks = r_WAITS[31:16];
  assign c_poll_div = r_POLL[15:0];
  assign c_fr_max = r_POLL[31:16];
  assign c_cis_addr = r_CIS_ADDR[31:0];
  assign c_cis_len = r_CIS_LEN[15:0];
  assign c_cor_addr = r_COR[14:0];
  assign c_cor_val = r_COR[22:15];
  assign c_tx_addr = r_TX_ADDR[31:0];
  assign c_tx_len = r_TX_LEN[15:0];
  assign c_rx_addr = r_RX_ADDR[31:0];
  assign c_rx_max = r_RX_MAX[15:0];
  assign c_power_on = p_CMD[0:0];
  assign c_power_off = p_CMD[1:1];
  assign c_cis_read = p_CMD[2:2];
  assign c_cor_write = p_CMD[3:3];
  assign c_if_reset = p_CMD[4:4];
  assign c_tx_start = p_CMD[5:5];
  assign c_rx_arm = p_CMD[6:6];

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_det;
    irq_set[1] = c_rdy;
    irq_set[2] = c_cfg;
    irq_set[3] = c_tx_done;
    irq_set[4] = c_rx;
    irq_set[5] = c_ireq;
    irq_set[6] = c_bus_to;
    irq_set[7] = c_err_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CTRL);
      10'd6: apb_rdata = 32'(r_TIMING);
      10'd7: apb_rdata = 32'(r_WAITS);
      10'd8: apb_rdata = 32'(r_POLL);
      10'd9: apb_rdata = 32'(r_CIS_ADDR);
      10'd10: apb_rdata = 32'(r_CIS_LEN);
      10'd11: apb_rdata = 32'(r_COR);
      10'd12: apb_rdata = 32'(r_TX_ADDR);
      10'd13: apb_rdata = 32'(r_TX_LEN);
      10'd14: apb_rdata = 32'(r_RX_ADDR);
      10'd15: apb_rdata = 32'(r_RX_MAX);
      10'd17: apb_rdata = 32'({c_present, c_err, c_tx_fail, c_rx_ovf, c_rx_full, c_busy, c_io_mode, c_ready, c_powered});
      10'd18: apb_rdata = 32'({c_last_st});
      10'd19: apb_rdata = 32'({c_rx_len});
      10'd20: apb_rdata = 32'({c_rx_cnt, c_tx_cnt});
      10'd21: apb_rdata = 32'({c_to_cnt, c_ts_cnt});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
